import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long small = nextLong(), big = nextLong();
        long area = small + 4 * big, side = (long) Math.sqrt((double) area);
        while (side * side > area) side--;
        while ((side + 1) * (side + 1) <= area) side++;
        // an odd side needs 2*side-1 unit tiles along the border the 2x2 tiles cannot cover
        if (side % 2 == 1 && small < 2 * side - 1) side--;
        System.out.println(side);
    }
}

package main

import (
	"fmt"
	"io"
	"math"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	small, big := nextInt(), nextInt()
	area := small + 4*big
	side := int64(math.Sqrt(float64(area)))
	for side*side > area {
		side--
	}
	for (side+1)*(side+1) <= area {
		side++
	}
	// an odd side needs 2*side-1 unit tiles along the border the 2x2 tiles cannot cover
	if side%2 == 1 && small < 2*side-1 {
		side--
	}
